audio_b64s = [url.split(",", 1)[1] for url in audio_data_urls]
<% } %><% } %>
headers = {
    "Authorization": "Bearer $NVIDIA_API_KEY",
    "Accept": "text/event-stream" if stream else "application/json",
}

payload = <%- renderedPayload %>

