find_media_path() {
  local kind="$1"
  local index="$2"
  shift 2
  local ext path
  for ext in "$@"; do
    path="${kind}_${index}.${ext}"
    if [ -f "$path" ]; then
      echo "$path"
      return 0
    fi
  done
  echo "Expected ${kind}_${index}.$*" >&2
  return 1
}

media_b64() {
  base64 < "$1" | tr -d '\n'
}

